import { useState } from 'react';
import './App.css';
import './components/style.css';

function App() {
  const [TodoArray, setTodoArray] = useState([])
  const [IdNumber, setIdNumber] = useState(1)

  function addTodoItem(text) {
    //...TodoArray is a copy of the array.
    //We then add a new object to the array with 4 key-value pairs
    setTodoArray([...TodoArray, {text, completed: false, id: IdNumber, timestamp: Date.now()}])
    setIdNumber(IdNumber+1)  
  }



  let n=document.querySelector('.input')


  console.log(n.value)
  return (
    <div className="App">
      <header>
        <div className='container'>
           <h1>To-Do List Manager</h1>
        </div>
      </header>
      <section className='contents'>
        <div className='container'>
          <input type='text' placeholder='Enter Task bruh' className='input'></input>
          <button className='addButton' onClick={addTodoItem()}>ADD</button>
          <toDoItems />
        </div>

      </section>
    </div>
  );
}

export default App;
